import json
import re


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def extract_id(link):
    if not isinstance(link, dict):
        return ""
    url = ((link.get("links") or {}).get("self")) or ""
    m = re.search(r"/(\d+)(?:$|\?)", str(url))
    return m.group(1) if m else ""


practices = []
try:
    entries = api.files.list(path="PracticeManager/Practices", scope="org")
except Exception:
    entries = []
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    slug = str(fname)[:-5]
    practice = read_json("PracticeManager/Practices/" + fname, {}) or {}
    if practice:
        practices.append({"slug": slug, "practice": practice})

new_items = []
for p in practices:
    business_id = str(p["practice"].get("cliniko_business_id") or "")
    if not business_id:
        continue
    seen = read_json("PracticeManager/CancellationSeen/" + p["slug"] + ".json", []) or []
    seen_ids = {str(x) for x in seen}
    try:
        result = api.connectors.invoke(
            server="cliniko-scheduling", tool="list_individual_appointments",
            args={"q": ["business_id:=" + business_id], "sort": "starts_at:desc", "per_page": 50},
        )
        rows = (result or {}).get("individual_appointments") or []
    except Exception:
        rows = []
    for row in rows:
        appt_id = str(row.get("id") or "")
        if not appt_id or appt_id in seen_ids or not row.get("cancelled_at"):
            continue
        new_items.append({
            "slug": p["slug"], "practice": p["practice"], "appointment_id": appt_id,
            "patient_name": row.get("patient_name") or "",
            "patient_id": extract_id(row.get("patient")),
            "practitioner_id": extract_id(row.get("practitioner")),
            "business_id": business_id,
            "appointment_type_id": extract_id(row.get("appointment_type")),
            "starts_at": row.get("starts_at") or "",
        })

import json
import datetime

AI_PROMPT = (
    "You are drafting a short, warm email on behalf of a healthcare clinic to a patient who just cancelled their "
    "appointment. Offer the real available times given, in the tone instructed. Never give clinical advice, "
    "diagnosis or interpretation. Keep it under 120 words."
)
AI_HINT = '{"subject": "", "body": ""}'


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def format_time(iso):
    return str(iso or "").replace("T", " ").replace("Z", " UTC")


def parse_iso(iso):
    try:
        s = str(iso or "").replace("Z", "+00:00")
        dt = datetime.datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except Exception:
        return None


item = params.get("item") or {}
slug = item.get("slug") or ""
practice = item.get("practice") or {}
appointment_id = item.get("appointment_id") or ""
patient_id = item.get("patient_id") or ""
patient_name = item.get("patient_name") or "this patient"
outcome = "skipped"

if slug and appointment_id:
    seen_path = "PracticeManager/CancellationSeen/" + slug + ".json"
    seen = read_json(seen_path, []) or []
    seen_set = {str(x) for x in seen}
    seen_set.add(appointment_id)
    write_json(seen_path, sorted(seen_set))

    policy = practice.get("policy") or {}
    window_hours = policy.get("cancellation_window_hours") or 24
    starts_at = parse_iso(item.get("starts_at"))
    now = datetime.datetime.now(datetime.timezone.utc)
    hours_until = ((starts_at - now).total_seconds() / 3600.0) if starts_at else None

    reviewer = practice.get("reviewer_id") or ""

    if hours_until is None or hours_until < window_hours:
        # Inside the cancellation window (or already passed, or the date couldn't be read) - per policy this
        # stops being auto-offered a new slot; flag for the practitioner's own judgement instead.
        api.workq.create(
            title="Late cancellation: " + patient_name,
            scope="org",
            description=(
                patient_name + " cancelled their " + format_time(item.get("starts_at")) + " appointment "
                + "inside the " + str(window_hours) + "-hour cancellation window (or the date couldn't be read). "
                "Per policy this isn't auto-offered a new slot - handle by hand."
            ),
            priority="normal",
            assignee_ids=[reviewer] if reviewer else None,
            labels=["healthcare-practice-management", "cancellation", "late-cancellation"],
        )
        outcome = "flagged_late_cancellation"
    else:
        email = ""
        if patient_id:
            try:
                patient = api.connectors.invoke(server="cliniko-patients", tool="get_patient", args={"id": patient_id})
                email = (patient or {}).get("email") or ""
            except Exception:
                email = ""

        slots = []
        if item.get("practitioner_id") and item.get("business_id") and item.get("appointment_type_id"):
            try:
                avail = api.connectors.invoke(
                    server="cliniko-scheduling", tool="get_available_times",
                    args={"business_id": item["business_id"], "practitioner_id": item["practitioner_id"], "appointment_type_id": item["appointment_type_id"]},
                )
                raw_slots = avail if isinstance(avail, list) else (avail or {}).get("available_times") or []
                for s in raw_slots[:3]:
                    t = s.get("appointment_start") if isinstance(s, dict) else s
                    if t:
                        slots.append(format_time(t))
            except Exception:
                slots = []

        tone = policy.get("tone") or "warm, concise, no jargon"
        try:
            drafted = api.ai.extract(
                prompt=AI_PROMPT,
                input=json.dumps({"patient_name": patient_name, "cancelled_time": format_time(item.get("starts_at")), "available_times": slots, "tone": tone}),
                schema_hint=AI_HINT,
            )
        except Exception:
            drafted = {}
        drafted = drafted if isinstance(drafted, dict) else {}
        subject = drafted.get("subject") or "Rebooking after your cancellation"
        body = drafted.get("body") or (
            "Hi " + patient_name + ", sorry to see your appointment cancelled. Here are some times to rebook: "
            + ", ".join(slots)
        )

        description = (
            "**Patient:** " + patient_name + "  \n"
            "**Cancelled appointment:** " + format_time(item.get("starts_at")) + "  \n"
            "**Email on file:** " + (email or "none on file") + "  \n\n"
            "**Drafted subject:** " + subject + "  \n\n"
            "**Drafted message:**\n\n" + body
        )
        if not email:
            description += "\n\n_No email on file for this patient - \"Send as drafted\" won't be able to send._"

        workq_item = api.workq.create(
            title="Cancellation reschedule offer: " + patient_name,
            scope="org",
            description=description,
            priority="normal",
            assignee_ids=[reviewer] if reviewer else None,
            labels=["healthcare-practice-management", "cancellation"],
        )
        workq_id = workq_item["id"]
        api.workq.attach_form(todo_id=workq_id, form_id=params["approval_form"])

        # Same accepted trade-off as the reschedule-request automation: reuses the no-show pair's
        # existing, tested draft-file folder/shape rather than editing code we don't own.
        write_json("PracticeManager/NoShowDrafts/" + workq_id + ".json", {
            "slug": slug,
            "appointment_id": appointment_id,
            "patient_id": patient_id,
            "patient_name": patient_name,
            "email": email,
            "subject": subject,
            "body": body,
        })
        outcome = "requested_approval"
